INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(1,'唉~小仙童你去幫我收集材料吧~讓我練一下合成~','["1", "唉~小仙童你去帮我收集材料吧~让我练一下合成~"]','server_implementation/data/evidence_raw/DailyMission01.csv',3,'client_csv',0);
