INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(3,'太好了！合出來的東西，多的就當是我賞你的~沒多就算啦。','["3", "太好了！合出来的东西，多的就当是我赏你的~没多就算啦。"]','server_implementation/data/evidence_raw/DailyMission01.csv',5,'client_csv',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(4,'不知道那個愛哭鬼她練到多少級了，希望差我很多。','["4", "不知道那个爱哭鬼她练到多少级了，希望差我很多。"]','server_implementation/data/evidence_raw/DailyMission01.csv',6,'client_csv',0);
