INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(8,'嗯，這樣應該就能贏過那個討厭鬼了吧？!','["8", "嗯，这样应该就能赢过那个讨厌鬼了吧?!"]','server_implementation/data/evidence_raw/DailyMission01.csv',10,'client_csv',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(9,'小仙童，我一直想要天池內的神魚，雪白、墨黑、透明、七彩錦鱗魚，可惜我是凡人，無法上仙界天池內找尋。你是否能幫忙帶其中一種下來給我？只要一尾，我的畢生大作即可問世，拜托了。','["9", "小仙童，我一直想要天池内的神鱼，雪白、墨黑、透明、七彩锦鳞鱼，可惜我是凡人，无法上仙界天池内找寻。你是否能帮忙带其中一种下来给我?只要一尾，我的毕生大作即可问世，拜托了。"]','server_implementation/data/evidence_raw/DailyMission01.csv',11,'client_csv',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(10,'崑侖仙界天池內有神奇的錦鱗魚，分別是雪白、墨黑、透明、七彩，其中透明與七彩最為罕見。\n當然如果你身上有比較罕見的，我會先從罕見的開始拿喔~嘿嘿~','["10", "昆仑仙界天池内有神奇的锦鳞鱼，分别是雪白、墨黑、透明、七彩，其中透明与七彩最为罕见。\\n当然如果你身上有比较罕见的，我会先从罕见的开始拿喔~嘿嘿~"]','server_implementation/data/evidence_raw/DailyMission01.csv',12,'client_csv',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(11,'這真是太神奇了，好特別的色澤，我就以這微薄的經驗值跟仙幣報答你吧，謝謝你。','["11", "这真是太神奇了，好特别的色泽，我就以这微薄的经验值跟仙币报答你吧，谢谢你。"]','server_implementation/data/evidence_raw/DailyMission01.csv',13,'client_csv',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(12,'這麼特別的魚，我該用煮的還是用蒸的好呢？這還真是苦惱啊…','["12", "这么特别的鱼，我该用煮的还是用蒸的好呢？这还真是苦恼啊…"]','server_implementation/data/evidence_raw/DailyMission01.csv',14,'client_csv',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(13,'唉，真是老糊塗竟然將包裹掉在聖譙原野的火雲碑附近，可以幫忙取回嗎？','["13", "唉，真是老糊涂竟然将包裹掉在圣谯原野的火云碑附近，可以帮忙取回吗？"]','server_implementation/data/evidence_raw/DailyMission01.csv',15,'client_csv',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(14,'幫個忙吧，就在火雲碑那邊。請帶著給你的「遺落的包裹清單」','["14", "帮个忙吧，就在火云碑那边。请带着给你的「遗落的包裹清单」"]','server_implementation/data/evidence_raw/DailyMission01.csv',16,'client_csv',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(15,'終於找回來了嗎？真是感謝啊，我多準備了一些東西，運氣好相同的獎勵可以拿到兩份喔。','["15", "终于找回来了吗?真是感谢啊，我多准备了一些东西，运气好相同的奖励可以拿到两份喔。"]','server_implementation/data/evidence_raw/DailyMission01.csv',17,'client_csv',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(16,'這可真是幫了我個大忙!!還好有找回包裹。還真是一直勞煩你，我有多準備一些謝禮給你。運氣好相同獎勵可以拿到兩份喔。','["16", "这可真是帮了我个大忙!!还好有找回包裹。还真是一直劳烦你，我有多准备一些谢礼给你。运气好相同奖励可以拿到两份喔。"]','server_implementation/data/evidence_raw/DailyMission01.csv',18,'client_csv',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(17,'小兄弟呀，幫我把這東西拿去給葛城的奚祈鑑定一下，看看是真是假。','["17", "小兄弟呀，帮我把这东西拿去给葛城的奚祈鉴定一下，看看是真是假。"]','server_implementation/data/evidence_raw/DailyMission01.csv',19,'client_csv',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(18,'將東西拿給葛城的奚祈鑑定。\n(聽說葛城有出土仙界的五彩玄鵲，而且還擺在雜貨店賣…這…真是暴殄天物啊。)','["18", "将东西拿给葛城的奚祈鉴定。\\n(听说葛城有出土仙界的五彩玄鹊，而且还摆在杂货店卖…这…真是暴殄天物啊。)"]','server_implementation/data/evidence_raw/DailyMission01.csv',20,'client_text_nls_traditional',0);
