INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(24,'將東西拿給九天冰屋的古旝鑑定。\n(聽說那邊的雜貨鋪有賣鎮魂霸印，不知道是真還是假？)','["24", "将东西拿给九天冰屋的古旝鉴定。\\n(听说那边的杂货铺有卖镇魂霸印，不知道是真还是假？)"]','server_implementation/data/evidence_raw/DailyMission01.csv',26,'client_csv',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(25,'將東西拿給焰霜鎮的甄麒鑑定。\n(陰陽兩儀盤，聽說那可以解開焰霜為什麼一邊是火島，一邊是冰島的秘密。)','["25", "将东西拿给焰霜镇的甄麒鉴定。\\n(阴阳两仪盘，听说那可以解开焰霜为什么一边是火岛，一边是冰岛的秘密。)"]','server_implementation/data/evidence_raw/DailyMission01.csv',27,'client_csv',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(26,'將東西拿給茄城的易褓鑑定。\n(聽說茄城前陣子從空中掉下很多仙雲劍柄，看來應該是仙界又有神魔大戰吧？劍柄似乎被擺在雜貨店里…)','["26", "将东西拿给茄城的易褓鉴定。\\n(听说茄城前阵子从空中掉下很多仙云剑柄，看来应该是仙界又有神魔大战吧？剑柄似乎被摆在杂货店里…)"]','server_implementation/data/evidence_raw/DailyMission01.csv',28,'client_csv',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(27,'是雲峰那老頭要你拿這東西給我鑑定？','["27", "是云峰那老头要你拿这东西给我鉴定？"]','server_implementation/data/evidence_raw/DailyMission01.csv',29,'client_csv',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(28,'這不用看都知道是假的，那瘋老頭又想拿這來騙錢，這邊雜貨店有其他古物，那應該也是假的，你買回去捉弄捉弄那老頭吧，跟他換值錢的東西吧。','["28", "这不用看都知道是假的，那疯老头又想拿这来骗钱，这边杂货店有其他古物，那应该也是假的，你买回去捉弄捉弄那老头吧，跟他换值钱的东西吧。"]','server_implementation/data/evidence_raw/DailyMission01.csv',30,'client_text_nls_traditional',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(29,'嗯，仔細觀察後……兩個都是假的。','["29", "嗯，仔细观察后……两个都是假的。"]','server_implementation/data/evidence_raw/DailyMission01.csv',31,'client_csv',0);
