INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(41,'小仙童，你看人界，似乎有黑影在蠢蠢慾動。我已經先派仙界守衛兵長下凡，駐守在人間了。你幫我把這令旗，拿給守衛兵長吧。','["41", "小仙童，你看人界，似乎有黑影在蠢蠢欲动。我已经先派仙界守卫兵长下凡，驻守在人间了。你帮我把这令旗，拿给守卫兵长吧。"]','server_implementation/data/evidence_raw/DailyMission01.csv',43,'client_csv',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(42,'嗯，我知道了，就拜托你把這警戒令交給駐守在楓華鎮仙界的守衛兵長吧。','["42", "嗯，我知道了，就拜托你把这警戒令交给驻守在楓華鎮仙界的守卫兵长吧。"]','server_implementation/data/evidence_raw/DailyMission01.csv',44,'client_csv',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(43,'大仙童的消息果力村這邊收到了，就麻煩小仙童把這警戒令交給駐守在果力村仙界的守衛兵長吧。','["43", "大仙童的消息果力村这边收到了，就麻烦小仙童把这警戒令交给驻守在果力村仙界的守卫兵长吧。"]','server_implementation/data/evidence_raw/DailyMission01.csv',45,'client_csv',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(44,'嗯，這下可得小心堤防了，小仙童就拜托你把這警戒令交給駐守在莫莫聚落仙界的守衛兵長吧。','["44", "嗯，这下可得小心堤防了，小仙童就拜托你把这警戒令交给驻守在莫莫聚落仙界的守卫兵长吧。"]','server_implementation/data/evidence_raw/DailyMission01.csv',46,'client_csv',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(45,'真是可靠的小仙童阿，人界的未來可要靠你們了，我這邊已經了解情況了，就請你將警戒令轉交給駐守在茄城仙界的守衛兵長吧。','["45", "真是可靠的小仙童阿，人界的未來可要靠你们了，我这边已经了解情况了，就请你将警戒令转交给驻守在茄城仙界的守卫兵长吧。"]','server_implementation/data/evidence_raw/DailyMission01.csv',47,'client_csv',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(46,'任務了解，請把這警戒令交給下一個駐守在果城仙界的守衛兵長。','["46", "任务了解，请把这警戒令交给下一个驻守在果城仙界的守卫兵长。"]','server_implementation/data/evidence_raw/DailyMission01.csv',48,'client_csv',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(47,'咦？又來了嗎？\n天啊，他們每天這樣來一張都不會煩的嗎？罷了罷了，把這警戒令拿給駐守在青采聚落仙界的守衛兵長吧。','["47", "咦?又来了吗?\\n天啊，他们每天这样来一张都不会烦的吗?罢了罢了，把这警戒令拿给驻守在青采聚落仙界的守卫兵长吧。"]','server_implementation/data/evidence_raw/DailyMission01.csv',49,'client_csv',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(48,'多謝，還得再麻煩你將這份警戒令交給駐守在九黎平原(寒羽荒原關卡口)的仙界守衛兵長了。','["48", "多谢，还得再麻烦你将这份警戒令交给驻守在九黎平原(寒羽荒原关卡口)的仙界守卫兵长了。"]','server_implementation/data/evidence_raw/DailyMission01.csv',50,'client_csv',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(49,'加油阿，小仙童，到我這已經快要結束了，你可要努力點撐過去，那就麻煩你把這份警戒令交給駐守在九黎平原(九尾國境關卡口)的仙界守衛兵長吧。','["49", "加油阿，小仙童，到我这已经快要结束了，你可要努力点撑过去，那就麻烦你把这份警戒令交给驻守在九黎平原(九尾国境关卡口)的仙界守卫兵长吧。"]','server_implementation/data/evidence_raw/DailyMission01.csv',51,'client_csv',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(50,'………………………………收到，看來我是最後一個了，就請你把這將警戒令還給在崑侖仙界的大仙童吧。','["50", "………………………………收到，看来我是最后一个了，就请你把这将警戒令还给在昆仑仙界的大仙童吧。"]','server_implementation/data/evidence_raw/DailyMission01.csv',52,'client_csv',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(51,'有邪惡氣息正在蔓延，看來人間又要大亂了。','["51", "有邪恶气息正在蔓延，看来人间又要大乱了。"]','server_implementation/data/evidence_raw/DailyMission01.csv',53,'client_csv',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(52,'嗯，我收到大仙童的指示了。謝謝你，小仙童。','["52", "嗯，我收到大仙童的指示了。谢谢你，小仙童。"]','server_implementation/data/evidence_raw/DailyMission01.csv',54,'client_csv',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(53,'大仙童一發不語的盯著人間看，似乎是在找尋什麼？','["53", "大仙童一发不语的盯着人间看，似乎是在找寻什么？"]','server_implementation/data/evidence_raw/DailyMission01.csv',55,'client_csv',0);
