INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(55,'辛苦你了，小仙童。','["55", "辛苦你了，小仙童。"]','server_implementation/data/evidence_raw/DailyMission01.csv',57,'client_csv',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(56,'這點經驗、道具就送你，讓你提升能力吧。','["56", "这点经验、道具就送你，让你提升能力吧。"]','server_implementation/data/evidence_raw/DailyMission01.csv',58,'client_csv',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(57,'吾家族世世代代守護著這座陵寢，如今被這群覬覦寶藏的鼠輩刁擾、破壞…，殺了那些囂張跋扈的「盜墓賊」，取下刀柄，回來找我。','["57", "吾家族世世代代守护着这座陵寝，如今被这群觊觎宝藏的鼠辈刁扰、破坏…，杀了那些嚣张跋扈的「盗墓贼」，取下刀柄，回来找我。"]','server_implementation/data/evidence_raw/DailyMission01.csv',59,'client_text_nls_traditional',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(58,'吾家族世世代代守護著這座陵寢，如今被這群窺覬奇兵的雜卒刁擾、破壞…，殺了那些無頭無腦的「秘密部隊」，取下徽章，回來找我。','["58", "吾家族世世代代守护着这座陵寝，如今被这群窥觊奇兵的杂卒刁扰、破坏…，杀了那些无头无脑的「秘密部队」，取下徽章，回来找我。"]','server_implementation/data/evidence_raw/DailyMission01.csv',60,'client_text_nls_traditional',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(59,'吾家族世世代代守護著這座陵寢，如今被這群貪婪神功的孬種刁擾、破壞…，殺了那些心存邪念的「刀劍師傅」，取下手鐲，回來找我。','["59", "吾家族世世代代守护着这座陵寝，如今被这群贪婪神功的孬种刁扰、破坏…，杀了那些心存邪念的「刀剑师傅」，取下手镯，回来找我。"]','server_implementation/data/evidence_raw/DailyMission01.csv',61,'client_text_nls_traditional',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(60,'吾家族世世代代守護著這座陵寢，替我去里面安撫受到驚嚇的「遺族亡魂」，祂們會在里面亂飄………取得感謝文，回來找我。','["60", "吾家族世世代代守护着这座陵寝，替我去里面安抚受到惊吓的「遗族亡魂」，祂们会在里面乱飘………取得感谢文，回来找我。"]','server_implementation/data/evidence_raw/DailyMission01.csv',62,'client_text_nls_traditional',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(61,'殺了囂張跋扈的盜墓賊，取下刀柄15個，回來找我。','["61", "杀了嚣张跋扈的盗墓贼，取下刀柄15个，回来找我。"]','server_implementation/data/evidence_raw/DailyMission01.csv',63,'client_csv',0);
