INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(105,'那些可惡的怪物，竟然傷害這麼可愛的兔子。小仙童啊，使用攝魂鏡收伏那些可惡的怪物吧。[攝魂鏡請跟受傷的仙兔(葛城 204/159)取得]','["105", "那些可恶的怪物，竟然伤害这么可爱的兔子。小仙童啊，使用摄魂镜收伏那些可恶的怪物吧。[摄魂镜请跟受伤的仙兔(葛城 204/159)取得]"]','server_implementation/data/evidence_raw/DailyMission01.csv',107,'client_csv',0);
