INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(112,'還不錯，以次貴的價格買到(低價的「琉璃沙」跟高價的「夜明珠」)…還有待加強。嗯…這是您花費金額的3倍獎金謝禮。','["112", "还不错，以次贵的价格买到(低价的「琉璃沙」跟高价的「夜明珠」)…还有待加强。嗯…这是您花费金额的3倍奖金谢礼。"]','server_implementation/data/evidence_raw/DailyMission01.csv',114,'client_csv',0);
