INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(114,'厲害，這看起來就是用最低價格的兩樣物品合出來的(低價「琉璃沙」與低價的「夜明珠」)。來！您可以獲得花費金額的10倍獎金謝禮。','["114", "厉害，这看起来就是用最低价格的两样物品合出来的(低价「琉璃沙」与低价的「夜明珠」)。来！您可以获得花费金额的10倍奖金谢礼。"]','server_implementation/data/evidence_raw/DailyMission01.csv',116,'client_csv',0);
