INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(116,'挑戰聖獸試煉，闖過第75關或是第150關，拿其中一個證明來，必有厚賞。一天只有一次機會~','["116", "挑战圣兽试炼，闯过第75关或是第150关，拿其中一个证明来，必有厚赏。一天只有一次机会~"]','server_implementation/data/evidence_raw/DailyMission01.csv',118,'client_csv',0);
