INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(120,'小伙子，我發現全新的省錢方法了。把診辛的「鉛製小馬」與郝益的「鍍金沙」合成「鍍金小馬」後給我。','["120", "小伙子，我发现全新的省钱方法了。把诊辛的「铅制小马」与郝益的「镀金沙」合成「镀金小马」后给我。"]','server_implementation/data/evidence_raw/DailyMission01.csv',122,'client_csv',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(121,'診辛(茄城 145/125)，郝益(莫莫聚落 85/85)。你花的錢越少，我給你的獎金倍數就越多。','["121", "诊辛(茄城 145/125)，郝益(莫莫聚落 85/85)。你花的钱越少，我给你的奖金倍数就越多。"]','server_implementation/data/evidence_raw/DailyMission01.csv',123,'client_csv',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(122,'你竟然是用最高的成本合成(高價「鉛製小馬」與高價「鍍金沙」)。收下這次花費金額的1.1倍獎金謝禮吧，請記得利用低價時段購入物品來合成喔。','["122", "你竟然是用最高的成本合成(高价「铅制小马」与高价「镀金沙」)。收下这次花费金额的1.1倍奖金谢礼吧，请记得利用低价时段购入物品来合成喔。"]','server_implementation/data/evidence_raw/DailyMission01.csv',124,'client_csv',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(123,'使以次貴的成本合成(低價「鉛製小馬」與高價「鍍金沙」)請繼續努力。請收下花費金額的3倍獎金謝禮。','["123", "使以次贵的成本合成(低价「铅制小马」与高价「镀金沙」)请继续努力。请收下花费金额的3倍奖金谢礼。"]','server_implementation/data/evidence_raw/DailyMission01.csv',125,'client_csv',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(124,'很好，用次低的成本合成出(高價「鉛製小馬」與低價「鍍金沙」)。可以獲得花費金額的6倍獎金謝禮。','["124", "很好，用次低的成本合成出(高价「铅制小马」与低价「镀金沙」)。可以获得花费金额的6倍奖金谢礼。"]','server_implementation/data/evidence_raw/DailyMission01.csv',126,'client_csv',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(125,'厲害，竟然用最低成本合成出來(低價「鉛製小馬」與低價「鍍金沙」)。來！您可以獲得花費金額的10倍獎金謝禮。','["125", "厉害，竟然用最低成本合成出来(低价「铅制小马」与低价「镀金沙」)。来！您可以获得花费金额的10倍奖金谢礼。"]','server_implementation/data/evidence_raw/DailyMission01.csv',127,'client_csv',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(126,'小伙子，想賺錢嗎？診辛的「鉛製小馬」與郝益的「鍍金沙」合成「鍍金小馬」，每天限三次喔！','["126", "小伙子，想赚钱吗？诊辛的「铅制小马」与郝益的「镀金沙」合成「镀金小马」，每天限三次喔！"]','server_implementation/data/evidence_raw/DailyMission01.csv',128,'client_csv',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(127,'這，這是「黃金小馬」！？嗯…這麼特殊的東西還是用低價的「鉛製小馬」製作，那我用這些錢向你收購好了','["127", "这，这是「黄金小马」！？嗯…这么特殊的东西还是用低价的「铅制小马」制作，那我用这些钱向你收购好了"]','server_implementation/data/evidence_raw/DailyMission01.csv',129,'client_csv',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(128,'這，這是「黃金小馬」！？嗯…這麼特殊的東西不過是用高價的「鉛製小馬」製作，那我用這些錢向你收購好了','["128", "这，这是「黄金小马」！？嗯…这么特殊的东西不过是用高价的「铅制小马」制作，那我用这些钱向你收购好了"]','server_implementation/data/evidence_raw/DailyMission01.csv',130,'client_csv',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(129,'嗯，關於煉丹修行用的材料，能否幫忙收集？','["129", "嗯，关于炼丹修行用的材料，能否帮忙收集？"]','server_implementation/data/evidence_raw/DailyMission01.csv',131,'client_csv',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(130,'嗯…可否給我點酒？可以拿些藥品跟你兌換。','["130", "嗯…可否给我点酒？可以拿些药品跟你兑换。"]','server_implementation/data/evidence_raw/DailyMission01.csv',132,'client_csv',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(131,'聖樵原野的曲湖上的仙界靈草、仙界神花各5個','["131", "圣樵原野的曲湖上的仙界灵草、仙界神花各5个"]','server_implementation/data/evidence_raw/DailyMission01.csv',133,'client_csv',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(132,'請給我「生命魔力酒」八個。','["132", "请给我「生命魔力酒」八个。"]','server_implementation/data/evidence_raw/DailyMission01.csv',134,'client_csv',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(133,'嗯，還需要些材料繼續修練。','["133", "嗯，还需要些材料继续修练。"]','server_implementation/data/evidence_raw/DailyMission01.csv',135,'client_csv',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(134,'酒…又沒了嗎？','["134", "酒…又没了吗？"]','server_implementation/data/evidence_raw/DailyMission01.csv',136,'client_csv',0);
INSERT INTO god2_research._xjz_stage_daily_mission_message VALUES(135,'感謝你提供的材料，那這些藥品請收下。','["135", "感谢你提供的材料，那这些药品请收下。"]','server_implementation/data/evidence_raw/DailyMission01.csv',137,'client_csv',0);
