INSERT INTO god2_research._xjz_stage_activity_mission_service_template VALUES(267,'actmis_tw_20101229',67,'軍需品任務:為了準備與九尾國的戰爭，需要帶回生菜葉子，可從1星水耕生菜農夫身上獲得。在果城周圍有許多生菜農夫，為了準備戰爭而努力耕種。果城是他們的故鄉，如果有人侵犯，就算是農夫也會挺身而出，守衛家鄉。',1,'[{"slot":1,"item_id":15401,"quantity":20,"name_zh_tw":"生菜葉子","item_code":"Mis20001","category":"MIS02","subcategory":"6"}]','["67", "军需品任务:为了准备与九尾国的战争，需要带回生菜叶子，可从1星水耕生菜农夫身上获得。在果城周围有许多生菜农夫，为了准备战争而努力耕种。果城是他们的故乡，如果有人侵犯，就算是农夫也会挺身而出，守卫家乡。", "15401", "20", "0", "0", "0", "0", "0", "0"]','server_implementation/data/evidence_raw/ActMis.csv',71,'client_service_activity_mission',0);
INSERT INTO god2_research._xjz_stage_activity_mission_service_template VALUES(268,'actmis_tw_20101229',68,'軍需品任務:為了準備與九尾國的戰爭，需要帶回桃子果肉，可從1星水耕桃子雜工身上獲得。果城周圍有許多桃子雜工，為了準備戰爭而努力工作。果城是他們的故鄉，如果有人侵犯，就算是農夫也會挺身而出，守衛家鄉。',1,'[{"slot":1,"item_id":15402,"quantity":20,"name_zh_tw":"桃子果肉","item_code":"Mis20002","category":"MIS02","subcategory":"6"}]','["68", "军需品任务:为了准备与九尾国的战争，需要带回桃子果肉，可从1星水耕桃子杂工身上获得。果城周围有许多桃子杂工，为了准备战争而努力工作。果城是他们的故乡，如果有人侵犯，就算是农夫也会挺身而出，守卫家乡。", "15402", "20", "0", "0", "0", "0", "0", "0"]','server_implementation/data/evidence_raw/ActMis.csv',72,'client_service_activity_mission',0);
INSERT INTO god2_research._xjz_stage_activity_mission_service_template VALUES(269,'actmis_tw_20101229',69,'軍需品任務:為了準備與九尾國的戰爭，需要帶回櫻桃果肉，可從1星水耕櫻桃礦工身上獲得。果城周圍有許多櫻桃礦工，為了準備戰爭而努力採礦。果城是他們的故鄉，如果有人侵犯，就算是農夫也會挺身而出，守衛家鄉。',1,'[{"slot":1,"item_id":15403,"quantity":20,"name_zh_tw":"櫻桃果肉","item_code":"Mis20003","category":"MIS02","subcategory":"6"}]','["69", "军需品任务:为了准备与九尾国的战争，需要带回樱桃果肉，可从1星水耕樱桃矿工身上获得。果城周围有许多樱桃矿工，为了准备战争而努力采矿。果城是他们的故乡，如果有人侵犯，就算是农夫也会挺身而出，守卫家乡。", "15403", "20", "0", "0", "0", "0", "0", "0"]','server_implementation/data/evidence_raw/ActMis.csv',73,'client_service_activity_mission',0);
INSERT INTO god2_research._xjz_stage_activity_mission_service_template VALUES(270,'actmis_tw_20101229',70,'軍需品任務:為了準備與九尾國的戰爭，需要帶回巨花花粉，可從果城巨花身上獲得。這是經過九黎人特別培育的植物，會自己移動，通常用來協助防禦果城的安全。',1,'[{"slot":1,"item_id":15404,"quantity":20,"name_zh_tw":"巨花花粉","item_code":"Mis20004","category":"MIS02","subcategory":"6"}]','["70", "军需品任务:为了准备与九尾国的战争，需要带回巨花花粉，可从果城巨花身上获得。这是经过九黎人特别培育的植物，会自己移动，通常用来协助防御果城的安全。", "15404", "20", "0", "0", "0", "0", "0", "0"]','server_implementation/data/evidence_raw/ActMis.csv',74,'client_service_activity_mission',0);
