-- 460_intake_xjz_achievement_activity_csharp_evidence.sql
-- Purpose: ingest clean C# restored achievement, activity mission, and daily mission evidence without raw JSON exposure.
-- Source pack: XJZ-csharp-evidence-capture-pack-20260818.zip

DROP TABLE IF EXISTS god2_research._xjz_stage_achievement_template;
DROP TABLE IF EXISTS god2_research._xjz_stage_achievement_collect_rule;
DROP TABLE IF EXISTS god2_research._xjz_stage_achievement_service_template;
DROP TABLE IF EXISTS god2_research._xjz_stage_activity_mission_template;
DROP TABLE IF EXISTS god2_research._xjz_stage_activity_mission_requirement;
DROP TABLE IF EXISTS god2_research._xjz_stage_activity_mission_service_template;
DROP TABLE IF EXISTS god2_research._xjz_stage_daily_mission_template;
DROP TABLE IF EXISTS god2_research._xjz_stage_daily_mission_message;
DROP TABLE IF EXISTS god2_research._xjz_stage_daily_mission_service_template;

CREATE TABLE god2_research._xjz_stage_achievement_template (achievement_id INT PRIMARY KEY, category_id INT NOT NULL, name_zh_tw VARCHAR(160) NOT NULL, points INT NOT NULL, description_1_zh_tw TEXT NULL, description_2_zh_tw TEXT NULL, raw_source VARCHAR(255) NOT NULL, raw_line INT NULL, evidence_status VARCHAR(96) NOT NULL, packet_evidence_boundary INT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE god2_research._xjz_stage_achievement_collect_rule (id INT PRIMARY KEY, achievement_id INT NOT NULL, collect_count INT NOT NULL, collect_slot INT NOT NULL, collect_name_zh_tw VARCHAR(160) NOT NULL, raw_source VARCHAR(255) NOT NULL, raw_line INT NULL, evidence_status VARCHAR(96) NOT NULL, packet_evidence_boundary INT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE god2_research._xjz_stage_achievement_service_template (service_id INT PRIMARY KEY, achievement_id INT NOT NULL, category_id INT NOT NULL, name_zh_tw VARCHAR(160) NOT NULL, points INT NOT NULL, description_1_zh_tw TEXT NULL, description_2_zh_tw TEXT NULL, collect_rule_count INT NOT NULL, collect_total_count INT NOT NULL, collect_rules_json LONGTEXT NOT NULL, raw_source VARCHAR(255) NOT NULL, raw_line INT NULL, evidence_status VARCHAR(96) NOT NULL, packet_evidence_boundary INT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE god2_research._xjz_stage_activity_mission_template (id INT PRIMARY KEY, activity_source VARCHAR(128) NOT NULL, activity_mission_id INT NOT NULL, description_zh_tw TEXT NOT NULL, raw_json LONGTEXT NOT NULL, raw_source VARCHAR(255) NOT NULL, raw_line INT NULL, evidence_status VARCHAR(96) NOT NULL, packet_evidence_boundary INT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE god2_research._xjz_stage_activity_mission_requirement (id INT PRIMARY KEY, activity_source VARCHAR(128) NOT NULL, activity_mission_id INT NOT NULL, requirement_slot INT NOT NULL, item_id INT NOT NULL, quantity INT NOT NULL, raw_source VARCHAR(255) NOT NULL, raw_line INT NULL, evidence_status VARCHAR(96) NOT NULL, packet_evidence_boundary INT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE god2_research._xjz_stage_activity_mission_service_template (service_id INT PRIMARY KEY, activity_source VARCHAR(128) NOT NULL, activity_mission_id INT NOT NULL, description_zh_tw TEXT NOT NULL, requirement_count INT NOT NULL, requirements_json LONGTEXT NOT NULL, raw_json LONGTEXT NOT NULL, raw_source VARCHAR(255) NOT NULL, raw_line INT NULL, evidence_status VARCHAR(96) NOT NULL, packet_evidence_boundary INT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE god2_research._xjz_stage_daily_mission_template (id INT PRIMARY KEY, daily_mission_id INT NOT NULL, branch_id INT NOT NULL, name_zh_tw VARCHAR(160) NOT NULL, start_npc_id INT NULL, end_npc_id INT NULL, weekday_mask VARCHAR(32) NULL, start_time INT NULL, end_time INT NULL, check_mode VARCHAR(32) NULL, min_rebirth INT NULL, max_rebirth INT NULL, limit_text_zh_tw TEXT NULL, intro_1_zh_tw TEXT NULL, intro_2_zh_tw TEXT NULL, intro_3_zh_tw TEXT NULL, start_location_zh_tw VARCHAR(255) NULL, end_location_zh_tw VARCHAR(255) NULL, reward_text_zh_tw TEXT NULL, repeat_count INT NULL, raw_json LONGTEXT NOT NULL, raw_source VARCHAR(255) NOT NULL, raw_line INT NULL, evidence_status VARCHAR(96) NOT NULL, packet_evidence_boundary INT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE god2_research._xjz_stage_daily_mission_message (message_id INT PRIMARY KEY, text_zh_tw TEXT NOT NULL, raw_json LONGTEXT NOT NULL, raw_source VARCHAR(255) NOT NULL, raw_line INT NULL, evidence_status VARCHAR(96) NOT NULL, packet_evidence_boundary INT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE god2_research._xjz_stage_daily_mission_service_template (service_id INT PRIMARY KEY, daily_template_id INT NOT NULL, daily_mission_id INT NOT NULL, branch_id INT NOT NULL, name_zh_tw VARCHAR(160) NOT NULL, start_npc_id INT NULL, end_npc_id INT NULL, weekday_mask VARCHAR(32) NULL, start_time INT NULL, end_time INT NULL, check_mode VARCHAR(32) NULL, min_rebirth INT NULL, max_rebirth INT NULL, limit_text_zh_tw TEXT NULL, intro_json LONGTEXT NOT NULL, start_location_zh_tw VARCHAR(255) NULL, end_location_zh_tw VARCHAR(255) NULL, reward_text_zh_tw TEXT NULL, repeat_count INT NULL, reward_count INT NOT NULL, rewards_json LONGTEXT NOT NULL, raw_json LONGTEXT NOT NULL, raw_source VARCHAR(255) NOT NULL, raw_line INT NULL, evidence_status VARCHAR(96) NOT NULL, packet_evidence_boundary INT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS god2_research.xjz_achievement_templates_evidence (
  achievement_id INT NOT NULL,
  category_id INT NOT NULL,
  name_zh_tw VARCHAR(160) NOT NULL,
  points INT NOT NULL,
  description_zh_tw TEXT NULL,
  operation_hint_zh_tw TEXT NULL,
  collect_rule_count INT NOT NULL DEFAULT 0,
  collect_total_count INT NOT NULL DEFAULT 0,
  source_line INT NULL,
  evidence_status_zh_tw VARCHAR(96) NOT NULL,
  needs_packet_evidence INT NOT NULL,
  PRIMARY KEY (achievement_id),
  KEY ix_xjz_achievement_category (category_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='C#證據包：成就模板候選。';

CREATE TABLE IF NOT EXISTS god2_research.xjz_achievement_collect_rules_evidence (
  collect_rule_id INT NOT NULL,
  achievement_id INT NOT NULL,
  collect_count INT NOT NULL,
  collect_slot INT NOT NULL,
  collect_name_zh_tw VARCHAR(160) NOT NULL,
  source_line INT NULL,
  evidence_status_zh_tw VARCHAR(96) NOT NULL,
  needs_packet_evidence INT NOT NULL,
  PRIMARY KEY (collect_rule_id),
  KEY ix_xjz_achievement_collect_achievement (achievement_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='C#證據包：成就收藏需求候選。';

CREATE TABLE IF NOT EXISTS god2_research.xjz_activity_mission_templates_evidence (
  activity_template_id INT NOT NULL,
  activity_source_zh_tw VARCHAR(128) NOT NULL,
  activity_mission_id INT NOT NULL,
  description_zh_tw TEXT NOT NULL,
  requirement_count INT NOT NULL DEFAULT 0,
  source_line INT NULL,
  evidence_status_zh_tw VARCHAR(96) NOT NULL,
  needs_packet_evidence INT NOT NULL,
  PRIMARY KEY (activity_template_id),
  UNIQUE KEY ux_xjz_activity_mission (activity_source_zh_tw, activity_mission_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='C#證據包：活動任務模板候選。';

CREATE TABLE IF NOT EXISTS god2_research.xjz_activity_mission_requirements_evidence (
  requirement_id INT NOT NULL,
  activity_source_zh_tw VARCHAR(128) NOT NULL,
  activity_mission_id INT NOT NULL,
  requirement_slot INT NOT NULL,
  client_item_id INT NOT NULL,
  linked_formal_item_id BIGINT NULL,
  item_name_zh_tw VARCHAR(160) NULL,
  quantity INT NOT NULL,
  source_line INT NULL,
  evidence_status_zh_tw VARCHAR(96) NOT NULL,
  needs_packet_evidence INT NOT NULL,
  PRIMARY KEY (requirement_id),
  KEY ix_xjz_activity_requirement_item (linked_formal_item_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='C#證據包：活動任務需求道具候選。';

CREATE TABLE IF NOT EXISTS god2_research.xjz_daily_mission_templates_evidence (
  daily_template_id INT NOT NULL,
  daily_mission_id INT NOT NULL,
  branch_id INT NOT NULL,
  name_zh_tw VARCHAR(160) NOT NULL,
  start_npc_id INT NULL,
  end_npc_id INT NULL,
  weekday_mask_zh_tw VARCHAR(32) NULL,
  start_time INT NULL,
  end_time INT NULL,
  check_mode_zh_tw VARCHAR(32) NULL,
  min_rebirth INT NULL,
  max_rebirth INT NULL,
  limit_text_zh_tw TEXT NULL,
  intro_zh_tw TEXT NULL,
  start_location_zh_tw VARCHAR(255) NULL,
  end_location_zh_tw VARCHAR(255) NULL,
  reward_text_zh_tw TEXT NULL,
  repeat_count INT NULL,
  reward_count INT NOT NULL DEFAULT 0,
  source_line INT NULL,
  evidence_status_zh_tw VARCHAR(96) NOT NULL,
  needs_packet_evidence INT NOT NULL,
  PRIMARY KEY (daily_template_id),
  KEY ix_xjz_daily_mission_id (daily_mission_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='C#證據包：日常任務模板候選，排除原始JSON。';

CREATE TABLE IF NOT EXISTS god2_research.xjz_daily_mission_messages_evidence (
  message_id INT NOT NULL,
  text_zh_tw TEXT NOT NULL,
  source_line INT NULL,
  evidence_status_zh_tw VARCHAR(96) NOT NULL,
  needs_packet_evidence INT NOT NULL,
  PRIMARY KEY (message_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='C#證據包：日常任務對話文字候選。';

DELETE FROM god2_research.xjz_achievement_templates_evidence;
SELECT service.achievement_id, service.category_id, service.name_zh_tw, service.points, service.description_1_zh_tw, service.description_2_zh_tw, service.collect_rule_count, service.collect_total_count, service.raw_line, service.evidence_status, service.packet_evidence_boundary
FROM god2_research._xjz_stage_achievement_service_template service;

DELETE FROM god2_research.xjz_achievement_collect_rules_evidence;
SELECT id, achievement_id, collect_count, collect_slot, collect_name_zh_tw, raw_line, evidence_status, packet_evidence_boundary
FROM god2_research._xjz_stage_achievement_collect_rule;

DELETE FROM god2_research.xjz_activity_mission_templates_evidence;
SELECT service_id, activity_source, activity_mission_id, description_zh_tw, requirement_count, raw_line, evidence_status, packet_evidence_boundary
FROM god2_research._xjz_stage_activity_mission_service_template;

DELETE FROM god2_research.xjz_activity_mission_requirements_evidence;
SELECT r.id, r.activity_source, r.activity_mission_id, r.requirement_slot, r.item_id, i.item_id, i.name_zh_tw, r.quantity, r.raw_line, r.evidence_status, r.packet_evidence_boundary
FROM god2_research._xjz_stage_activity_mission_requirement r
LEFT JOIN god2_game.items i ON i.client_item_id = r.item_id;

DELETE FROM god2_research.xjz_daily_mission_templates_evidence;
SELECT service_id, daily_mission_id, branch_id, name_zh_tw, start_npc_id, end_npc_id, weekday_mask, start_time, end_time, check_mode, min_rebirth, max_rebirth, limit_text_zh_tw, TRIM(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(intro_json, '[', ''), ']', ''), '"', ''), ',', '；'), 'null', '')), start_location_zh_tw, end_location_zh_tw, reward_text_zh_tw, repeat_count, reward_count, raw_line, evidence_status, packet_evidence_boundary
FROM god2_research._xjz_stage_daily_mission_service_template;

DELETE FROM god2_research.xjz_daily_mission_messages_evidence;
SELECT message_id, text_zh_tw, raw_line, evidence_status, packet_evidence_boundary
FROM god2_research._xjz_stage_daily_mission_message;

CREATE OR REPLACE VIEW god2_research.vw_xjz_achievement_activity_csharp_summary_zh_tw AS
SELECT '成就模板' AS 資料類型, COUNT(*) AS 筆數, SUM(needs_packet_evidence) AS 需要封包證據, SUM(points) AS 點數合計, NULL AS 已連正式道具, '成就系統顯示與條件入口' AS 遊戲功能
FROM god2_research.xjz_achievement_templates_evidence
UNION ALL
SELECT '成就收藏需求', COUNT(*), SUM(needs_packet_evidence), NULL, NULL, '收集類成就需求'
FROM god2_research.xjz_achievement_collect_rules_evidence
UNION ALL
SELECT '活動任務模板', COUNT(*), SUM(needs_packet_evidence), NULL, NULL, '活動任務清單與描述'
FROM god2_research.xjz_activity_mission_templates_evidence
UNION ALL
SELECT '活動任務需求', COUNT(*), SUM(needs_packet_evidence), NULL, SUM(CASE WHEN linked_formal_item_id IS NOT NULL THEN 1 ELSE 0 END), '活動任務需求道具與數量'
FROM god2_research.xjz_activity_mission_requirements_evidence
UNION ALL
SELECT '日常任務模板', COUNT(*), SUM(needs_packet_evidence), NULL, NULL, '每日/重複任務時間、NPC、說明與獎勵文字'
FROM god2_research.xjz_daily_mission_templates_evidence
UNION ALL
SELECT '日常任務訊息', COUNT(*), SUM(needs_packet_evidence), NULL, NULL, '日常任務對話文字'
FROM god2_research.xjz_daily_mission_messages_evidence;

CREATE OR REPLACE VIEW god2_research.vw_xjz_achievement_activity_text_quality_zh_tw AS
SELECT '成就模板' AS 資料表, COUNT(*) AS 疑似亂碼或簡體殘留
FROM god2_research.xjz_achievement_templates_evidence
WHERE CONCAT_WS('', name_zh_tw, description_zh_tw, operation_hint_zh_tw) REGEXP '[�锛绔閵鐧傚偡国庆黄欢类卖贩们圆质给]'
UNION ALL
SELECT '活動任務模板', COUNT(*)
FROM god2_research.xjz_activity_mission_templates_evidence
WHERE description_zh_tw REGEXP '[�锛绔閵鐧傚偡国庆黄欢类卖贩们圆质给]'
UNION ALL
SELECT '日常任務模板', COUNT(*)
FROM god2_research.xjz_daily_mission_templates_evidence
WHERE CONCAT_WS('', name_zh_tw, limit_text_zh_tw, intro_zh_tw, start_location_zh_tw, end_location_zh_tw, reward_text_zh_tw) REGEXP '[�锛绔閵鐧傚偡国庆黄欢类卖贩们圆质给]'
UNION ALL
SELECT '日常任務訊息', COUNT(*)
FROM god2_research.xjz_daily_mission_messages_evidence
WHERE text_zh_tw REGEXP '[�锛绔閵鐧傚偡国庆黄欢类卖贩们圆质给]';

UPDATE god2_research.xjz_csharp_zip_evidence_digest
SET current_project_status_zh_tw = '已匯入成就模板與收藏規則',
    safe_apply_level_zh_tw = '可用於成就服務候選；正式完成判定需事件觸發對照',
    next_server_action_zh_tw = '先建立成就顯示與收集需求對照；擊殺、任務、收集、強化等觸發事件需逐項接 runtime。',
    blocked_reason_zh_tw = '客戶端模板不等於伺服器完成判定。',
    related_project_object_zh_tw = 'migration 460, xjz_achievement_*'
WHERE evidence_key = 'achievement_sources';

UPDATE god2_research.xjz_csharp_zip_evidence_digest
SET current_project_status_zh_tw = '已匯入活動與日常任務候選',
    safe_apply_level_zh_tw = '可用於活動任務候選；正式排程與獎勵需後續驗證',
    next_server_action_zh_tw = '先使用需求道具連結建立活動任務對照；正式啟用前需確認活動時間、NPC流程與獎勵。',
    blocked_reason_zh_tw = '部分日常獎勵文字來源有亂碼風險，已只保留可讀欄位並提供品質掃描。',
    related_project_object_zh_tw = 'migration 460, xjz_activity_mission_*, xjz_daily_mission_*'
WHERE evidence_key = 'activity_mission_sources';

